def schedule(stages: int, microbatches: int) -> list:
    """One string per stage: the micro-batch index at each tick when busy, '.' when idle."""
    total_ticks = microbatches + stages - 1
    rows = []
    for s in range(stages):
        row = "".join(str(t - s) if 0 <= t - s < microbatches else "." for t in range(total_ticks))
        rows.append(row)
    return rows

for row in schedule(3, 4):
    print(row)
print("".join(schedule(3, 4)).count("."))
